// Prepare Image & Metadata
// Turns the Drive binary into exactly what the MultiSet VPS query needs:
// raw base64 (no data: prefix), the TRUE pixel size, and camera intrinsics.

// ---- CONFIG --------------------------------------------------------------
// Put the real intrinsics of the phone that took the photo here. Leave them
// null to estimate from the image width + HFOV_DEG: good enough for the toy
// example, not good enough for production.
const FX = null;
const FY = null;
const PX = null;
const PY = null;
const HFOV_DEG = 69;   // typical smartphone main-camera horizontal FOV
// --------------------------------------------------------------------------

const trg = $('Drive Trigger - New Snapshot').first().json;
const fileName = trg.name || 'report_unknown_object.jpg';
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');

function imageSize(b) {
  // PNG
  if (b.length > 24 && b.toString('ascii', 12, 16) === 'IHDR') {
    return { width: b.readUInt32BE(16), height: b.readUInt32BE(20) };
  }
  // JPEG: walk the marker segments until the SOFn frame header
  if (b[0] !== 0xFF || b[1] !== 0xD8) return null;
  let i = 2;
  while (i < b.length - 9) {
    if (b[i] !== 0xFF) { i++; continue; }
    const marker = b[i + 1];
    if (marker === 0xFF) { i++; continue; }
    if (marker === 0x01 || (marker >= 0xD0 && marker <= 0xD9)) { i += 2; continue; }
    const len = b.readUInt16BE(i + 2);
    const isSOF = marker >= 0xC0 && marker <= 0xCF &&
                  marker !== 0xC4 && marker !== 0xC8 && marker !== 0xCC;
    if (isSOF) return { height: b.readUInt16BE(i + 5), width: b.readUInt16BE(i + 7) };
    i += 2 + len;
  }
  return null;
}

const size = imageSize(buf) || { width: 960, height: 720 };
const fx = FX ?? Number(((size.width / 2) / Math.tan((HFOV_DEG * Math.PI / 180) / 2)).toFixed(4));
const fy = FY ?? fx;
const px = PX ?? size.width / 2;
const py = PY ?? size.height / 2;

// PoC filename convention: report_<reporterEmail>_<freeText>.jpg
const parts = fileName.replace(/\.[^.]+$/, '').split('_');
const reporterEmail = (parts[1] && parts[1].includes('@')) ? parts[1] : 'unknown@reporter';

const b64 = buf.toString('base64');

return [{
  json: {
    fileName,
    reporterEmail,
    photoUrl: trg.webViewLink || '',
    width: size.width,
    height: size.height,
    fx, fy, px, py,
    imageB64: b64,                               // -> MultiSet queryImage
    dataUri: 'data:image/jpeg;base64,' + b64,    // -> Vision LLM later on
  },
  binary: $input.first().binary,
}];

