const rows = $('Rank Candidates (SQL)').all().map(i => i.json).filter(r => r.email);
const ticketId = $('Create Ticket').first().json.id;
const trg = $('Parse Triage JSON').first().json;
// Deterministic scheduling: severity >= 4 -> next business day 08:00-10:00,
// otherwise +2 business days 14:00-16:00. (Constraint 2: fixed slot, no negotiation.)
function addBusinessDays(from, n) {
  const d = new Date(from); let added = 0;
  while (added < n) { d.setDate(d.getDate() + 1);
    if (d.getDay() !== 0 && d.getDay() !== 6) added++; }
  return d.toISOString().slice(0, 10);
}
const urgent = (trg.severity || 3) >= 4;
const proposedDate = addBusinessDays(new Date(), urgent ? 1 : 2);
const proposedSlot = urgent ? '08:00-10:00' : '14:00-16:00';
return rows.map((c, i) => ({ json: {
  technician_id: c.technician_id, full_name: c.full_name, email: c.email,
  rank: i + 1,
  reason: `open_jobs=${c.open_jobs}, last_assigned=${c.last_assigned_at || 'never'}, rating=${c.rating}`,
  ticketId, proposedDate, proposedSlot,
  elementName: trg.element.name, ifcClass: trg.element.ifc_class,
  description: trg.description, severity: trg.severity, photoUrl: trg.photoUrl
} }));
